/* ===== Logic ===== */
function pct(f,k){var v=f.n[k]||0;return Math.min(100,v/NUT[k][2]*100)}
function rawPct(f,k){return (f.n[k]||0)/NUT[k][2]*100}
var BEN=[
 ["Muscle gain",function(f){return pct(f,"protein")*1.2+pct(f,"magnesium")*.2}],
 ["Weight gain",function(f){return f.kcal/6}],
 ["Weight loss",function(f){return Math.max(0,pct(f,"fiber")*1.5+(f.kcal<60?40:f.kcal<120?15:0)-f.kcal/10)}],
 ["Blood count increase",function(f){return pct(f,"iron")*1.5+pct(f,"folate")+pct(f,"b12")*.7}],
 ["Healthy fat",function(f){return pct(f,"fat")*.8*f.fatQ+pct(f,"vite")*.2}],
 ["Strong bones",function(f){return pct(f,"calcium")+pct(f,"magnesium")*.3+pct(f,"vitk")*.3+pct(f,"vitd")*.5}],
 ["Instant energy",function(f){return Math.max(0,((f.n.carbs||0)-(f.n.fat||0)*.5)*3)+pct(f,"potassium")*.3}],
 ["Immunity and eyes",function(f){return pct(f,"vitc")*.5+pct(f,"vita")*.5+pct(f,"vite")*.3}],
 ["Heart health",function(f){return pct(f,"potassium")*.5+pct(f,"magnesium")*.4+pct(f,"fiber")*.5+pct(f,"fat")*.3*f.fatQ}],
 ["Better digestion",function(f){return pct(f,"fiber")*1.5+(f.n.water||0)/20}],
 ["Hydration",function(f){return Math.max(0,((f.n.water||0)-60)*1.2)+pct(f,"potassium")*.2}],
 ["Brain and nerves",function(f){return pct(f,"b12")*.6+pct(f,"b6")*.6+pct(f,"folate")*.5+pct(f,"vite")*.3+pct(f,"magnesium")*.2}],
 ["Skin and hair",function(f){return pct(f,"vitc")*.4+pct(f,"vite")*.5+pct(f,"vita")*.3+pct(f,"protein")*.3}]
];
